<?php
namespace Tests\Feature;
use App\Models\Ingredient;use App\Models\Product;use App\Models\ProductFlavor;use App\Models\ProductVariant;use App\Models\Recipe;use App\Models\Unit;use App\Models\User;use App\Services\RecipeResolver;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class ProductRecipeTest extends TestCase{use RefreshDatabase;
 public function test_half_pizza_uses_full_base_and_half_toppings():void{$this->seed();$u=User::first();$g=Unit::where('symbol','g')->first();$ingredients=collect(['Masa','Queso','Pepperoni','Jamón'])->mapWithKeys(fn($n)=>[$n=>Ingredient::create(['branch_id'=>$u->branch_id,'base_unit_id'=>$g->id,'name'=>$n])]);$p=Product::create(['branch_id'=>$u->branch_id,'name'=>'Pizza','type'=>'pizza']);$v=ProductVariant::create(['product_id'=>$p->id,'name'=>'Grande','price'=>200,'max_flavors'=>2,'allows_half_and_half'=>true]);$a=ProductFlavor::create(['product_id'=>$p->id,'name'=>'Pepperoni']);$b=ProductFlavor::create(['product_id'=>$p->id,'name'=>'Jamón']);foreach([[$a,$ingredients['Pepperoni']],[$b,$ingredients['Jamón']]] as [$flavor,$top]){$r=Recipe::create(['product_variant_id'=>$v->id,'product_flavor_id'=>$flavor->id,'name'=>$flavor->name]);$r->items()->createMany([['ingredient_id'=>$ingredients['Masa']->id,'quantity'=>350,'component'=>'base'],['ingredient_id'=>$ingredients['Queso']->id,'quantity'=>200,'component'=>'base'],['ingredient_id'=>$top->id,'quantity'=>100,'component'=>'topping']]);}$resolved=collect(app(RecipeResolver::class)->resolve($v,[$a->id,$b->id]))->keyBy('ingredient_id');$this->assertEquals(350,$resolved[$ingredients['Masa']->id]['quantity']);$this->assertEquals(200,$resolved[$ingredients['Queso']->id]['quantity']);$this->assertEquals(50,$resolved[$ingredients['Pepperoni']->id]['quantity']);$this->assertEquals(50,$resolved[$ingredients['Jamón']->id]['quantity']);}
 public function test_recipe_can_be_cloned_to_another_variant():void{$this->seed();$u=User::first();Sanctum::actingAs($u);$g=Unit::where('symbol','g')->first();$i=Ingredient::create(['branch_id'=>$u->branch_id,'base_unit_id'=>$g->id,'name'=>'Masa']);$p=Product::create(['branch_id'=>$u->branch_id,'name'=>'Pizza','type'=>'pizza']);$a=ProductVariant::create(['product_id'=>$p->id,'name'=>'Mediana','price'=>100]);$b=ProductVariant::create(['product_id'=>$p->id,'name'=>'Grande','price'=>150]);$recipe=Recipe::create(['product_variant_id'=>$a->id,'name'=>'Base']);$recipe->items()->create(['ingredient_id'=>$i->id,'quantity'=>250,'component'=>'base']);$this->postJson("/api/recipes/{$recipe->id}/clone",['product_variant_id'=>$b->id,'name'=>'Base grande'])->assertCreated()->assertJsonPath('items.0.quantity','250.0000');}
}
